-- Read-only catalog inventory; run on both projects. No row payloads or secrets.
select c.relname as name,c.relkind,c.relrowsecurity as rls,(select count(*) from pg_policy p where p.polrelid=c.oid) as policies,(select jsonb_agg(jsonb_build_object('name',t.tgname,'function',t.tgfoid::regproc::text)) from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal) as triggers from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('events','event_articles','articles','claims','article_claims','claim_evidence_links','explanations','pipeline_config','original_source_import_credentials','source_comparison_enrichment_queue','source_comparison_membership_release_policy','source_comparison_membership_scores','source_comparison_membership_audits') order by c.relname;
